// Unit-only wire/process substitutes. No Chrome, actual encoder or output movie.
const fs=require('fs'),path=require('path'),cp=require('child_process'),Module=require('module'),{EventEmitter}=require('events'),{PassThrough}=require('stream');
const dir=process.env.FABLECUT_EXPORT_UNIT_GATE,kind=process.env.FABLECUT_EXPORT_UNIT_KIND;
if(dir){
 const load=Module._load;Module._load=function(request,parent,...rest){const mod=load.call(this,request,parent,...rest);if(request==='./export-jobs'&&parent?.filename.endsWith('server.js')&&kind!=='no-browser')return {...mod,createExportJobs:opts=>mod.createExportJobs({...opts,launchBrowser:()=>{}})};if(request==='./export-snapshot'&&parent?.filename.endsWith('server.js')&&kind==='capture')return {...mod,capture:async(...args)=>{const snapshot=await mod.capture(...args);await new Promise(resolve=>ready(resolve,[]));return snapshot;}};return mod;};
 const ready=(fn,args)=>{fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'ready'),'unit');const timer=setInterval(()=>{if(fs.existsSync(path.join(dir,'release'))){clearInterval(timer);fn(...args);}},10);};
 const sync=cp.spawnSync;cp.spawnSync=function(cmd,args,...rest){if(cmd==='ffmpeg'&&args.includes('-version'))return {status:0,stdout:Buffer.from('unit substitute')};return sync.call(this,cmd,args,...rest);};
 const exec=cp.execFile;cp.execFile=function(cmd,args,...rest){if(cmd==='ffmpeg'&&args.some(v=>String(v).includes('loudnorm='))&&kind==='recovery-loudnorm'){const fn=rest.find(v=>typeof v==='function'),proc=new EventEmitter();proc.exitCode=null;proc.signalCode=null;fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'loudnorm-started'),'unit');proc.kill=()=>{fs.writeFileSync(path.join(dir,'loudnorm-stop'),'unit');setTimeout(()=>{proc.exitCode=1;proc.signalCode='SIGTERM';fn(Error('unit stopped'),'', '');proc.emit('close',1);},50);};return proc;}if(cmd==='ffmpeg'&&args.includes('lavfi')){const fn=rest.find(v=>typeof v==='function');setTimeout(()=>fn(kind==='recovery-dry-fail'?Object.assign(Error('unit preflight rejected'),{code:1}):null,'',kind==='recovery-dry-fail'?'unit preflight rejected':''),1);return {exitCode:0,signalCode:null,pid:undefined,kill(){}};}if(cmd==='ffmpeg'&&args.includes('-encoders')){const fn=rest.find(v=>typeof v==='function');const values=[null,' V..... libx264 H264\n A..... aac AAC\n',''];if(kind==='admission')ready(fn,values);else setTimeout(()=>fn(...values),1);return {pid:undefined,kill(){}};}return exec.call(this,cmd,args,...rest);};
 const spawn=cp.spawn;cp.spawn=function(cmd,args,...rest){if(cmd==='ffmpeg'&&!args.includes('lavfi')&&String(kind||'').startsWith('recovery-')){const proc=new EventEmitter();proc.exitCode=null;proc.signalCode=null;proc.killed=false;proc.stderr=new PassThrough();proc.stdin=new PassThrough();fs.mkdirSync(dir,{recursive:true});fs.appendFileSync(path.join(dir,'encoder-started'),'unit\n');const output=args[args.length-1];if(typeof output==='string'&&output.includes('.part.'))fs.appendFileSync(output,Buffer.alloc(48,1));const close=()=>{if(proc.exitCode!==null)return;proc.exitCode=1;proc.signalCode='SIGTERM';proc.emit('close',1);};proc.kill=signal=>{fs.appendFileSync(path.join(dir,'encoder-kills'),signal+'\n');if(kind!=='recovery-cleanup-unconfirmed'){proc.killed=true;setTimeout(close,30);}return true;};if(kind==='recovery-frame-queue')proc.stdin.write=()=>false;const timer=setInterval(()=>{if(fs.existsSync(path.join(dir,'encoder-release'))){clearInterval(timer);close();}},10);timer.unref();proc.once('close',()=>clearInterval(timer));return proc;}if(cmd==='ffmpeg'&&args.includes('lavfi')){const proc=new EventEmitter();proc.stderr=new PassThrough();proc.stdin=new PassThrough();proc.kill=()=>{};const on=proc.on.bind(proc);proc.on=(name,fn)=>{if(name==='close'){if(kind==='begin')ready(fn,[0]);else setTimeout(()=>fn(0),1);return proc;}return on(name,fn);};return proc;}return spawn.call(this,cmd,args,...rest);};
}
